SELECT DATE_TRUNC('MONTH', ss.sale_date) AS sale_month, ss.store_id, ROUND(AVG(i.quantity), 2) AS avg_quantity FROM inventory i LEFT JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE ss.store_id = 2 GROUP BY DATE_TRUNC('MONTH', ss.sale_date), ss.store_id HAVING ROUND(AVG(i.quantity), 2) > 54 ORDER BY avg_quantity DESC
